mapper.select:
SELECT * FROM learning_behavior_log
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}

SELECT COALESCE(SUM(duration), 0)
FROM learning_behavior_log
WHERE user_id = #{userId}

SELECT l.* FROM learning_behavior_log l

    INNER JOIN learning_task t ON l.task_no = t.task_no



        AND l.user_id = #{userId}


        AND l.user_type = #{userType}


        AND l.action_type = #{actionType}


        AND l.resource_type = #{resourceType}


        AND t.course_code = #{courseId}


        AND l.created_at >= #{startTime}


        AND l.created_at <= #{endTime}


ORDER BY l.created_at DESC
